-- Player write-ups, notable facts and monthly goals and assists from the almanac (data/league-2025-26.json).
-- Data, not schema. Apply once after the player_almanac migration, e.g.
--   supabase db query --remote -f supabase/seed_almanac_players.sql
-- Safe to run again. Players are matched by roster nickname.
-- The text was written during the 2025/26 season, so figures written into a sentence are as they were then.
-- The site lists Ohis twice and Ikah twice (as Ikhaz): each pair is merged. Oreos is Oriola's cup-only row and is left out.
insert into player_almanac (player_id, write_up, facts, months)
select p.id, a.write_up, a.facts, a.months
from (values
  ('AK', '**AK** came out of the blocks faster than anyone, _13 G+A in January_ and a share of the season''s first POTM with Kunle. It wasn''t a flash in the pan: 65 G+A from 43 goals and 22 assists, contributions in 9 of 10 months, and #7 on the table. **He and Ohis became the first brothers to both win POTM. The family business is booming.**', array['Shared January POTM with Kunle, both finished on 13 G+A', 'First brothers to both win POTM, alongside Ohis in March', 'Kept 3 clean sheets in GW20']::text[], '{"1":{"g":7,"a":6},"2":{"g":4,"a":2},"3":{"g":0,"a":0},"4":{"g":8,"a":2},"5":{"g":2,"a":2},"6":{"g":6,"a":2},"7":{"g":5,"a":0},"8":{"g":3,"a":3},"9":{"g":4,"a":2},"10":{"g":2,"a":1},"11":{"g":2,"a":2}}'::jsonb),
  ('Ajegs', '**Ajegs** is a keeper who plays like a sweeper with a passing range. _34 clean sheets_ and the February Golden Glove are the headline, but 12 assists from between the sticks is what sets him apart. **He makes the backline calmer and the counter quicker.**', array['12 clean sheets, third best behind Bass and Jerrie', 'Won the February Golden Glove with 7 CS', 'Assists in four of five months']::text[], '{"1":{"g":0,"a":0},"2":{"g":1,"a":3},"3":{"g":0,"a":1},"4":{"g":1,"a":2,"dotm":37},"5":{"g":0,"a":2,"dotm":78},"6":{"g":1,"a":0,"dotm":55},"7":{"g":1,"a":0,"dotm":55},"8":{"g":2,"a":1,"dotm":38},"9":{"g":0,"a":2,"dotm":24},"10":{"g":2,"a":1,"dotm":38},"11":{"g":0,"a":0,"dotm":10}}'::jsonb),
  ('Ajibola', '**Ajibola** is a grafter who keeps getting better. 7 goals and 8 assists so far, with his best return, _5 G+A_, arriving in September. **The trend line is pointing one way.**', array['Featured in DOTM tracking']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":1,"a":1},"5":{"g":2,"a":0},"6":{"g":0,"a":3},"7":{"g":0,"a":0},"8":{"g":2,"a":1},"9":{"g":2,"a":3},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Allison', '**Allison** is proof the table rewards patience. A quiet February and March gave way to a big summer, peaking at _9 G+A in July_. 30 G+A in total, 21 goals, 9 assists, plus 9 clean sheets on the defensive tracker. **She finishes stronger than she starts.**', array['May was by far his best month, 5 goals after near-zero output earlier', 'Scored in back-to-back game weeks twice']::text[], '{"1":{"g":1,"a":2},"2":{"g":0,"a":0},"3":{"g":0,"a":1},"4":{"g":2,"a":2,"dotm":34},"5":{"g":5,"a":0},"6":{"g":2,"a":3,"dotm":-1},"7":{"g":8,"a":1},"8":{"g":3,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0,"dotm":15},"11":{"g":0,"a":0}}'::jsonb),
  ('Bass', '**Bass** doesn''t do goals. He does clean sheets, _34 of them_, and three Golden Gloves (January, March, April) to prove it. Four shutouts in a single game week is a joint league record. **Not one yellow card all season. Calm is the whole game.**', array['32 clean sheets, the most in league history, 29% of all CS recorded', 'Won the Golden Glove three times: January, March and April', '4 clean sheets in a single GW (GW16), joint league record', 'Zero yellow cards in 26 game weeks']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":1},"3":{"g":0,"a":1},"4":{"g":0,"a":1,"dotm":52},"5":{"g":0,"a":0,"dotm":47},"6":{"g":0,"a":0,"dotm":25},"7":{"g":1,"a":0,"dotm":23},"8":{"g":0,"a":0,"dotm":25},"9":{"g":0,"a":1,"dotm":47},"10":{"g":0,"a":0,"dotm":20},"11":{"g":0,"a":0,"dotm":25}}'::jsonb),
  ('Bald Hermit', '**Busayo** is the complete midfield package. _47 G+A and 41 clean sheets_, a share of the March Golden Glove and the July Playmaker award, silverware at both ends of the pitch. Best month: 9 G+A in May. **Zero cards. Zero fuss. First name on the team sheet.**', array['4 clean sheets in GW10, joint holder of the single-GW CS record', 'Contributed in all five months', '6 goals and 3 assists in May, career-best monthly totals']::text[], '{"1":{"g":1,"a":2},"2":{"g":3,"a":1},"3":{"g":1,"a":1},"4":{"g":2,"a":5,"dotm":45},"5":{"g":6,"a":3,"dotm":89},"6":{"g":3,"a":1,"dotm":51},"7":{"g":0,"a":6,"dotm":47},"8":{"g":1,"a":3,"dotm":64},"9":{"g":1,"a":0,"dotm":8},"10":{"g":0,"a":1,"dotm":42},"11":{"g":5,"a":1,"dotm":32}}'::jsonb),
  ('Chukkie', '**Chukkie** is a defender with a forward''s numbers. _74 G+A_, 36 goals, 38 assists, puts him #6 on the whole table. Then August happened: Playmaker of the Month and a _134-point DOTM haul_, the biggest monthly score the award has ever seen. **Defenders aren''t supposed to do this. Nobody told Chukkie.**', array['35 G+A, 7th all-time this season', 'Contributed in all five months with no complete blanks', 'Zero cards all season']::text[], '{"1":{"g":5,"a":4},"2":{"g":4,"a":3},"3":{"g":2,"a":3},"4":{"g":4,"a":1,"dotm":5},"5":{"g":6,"a":3,"dotm":8},"6":{"g":3,"a":2,"dotm":33},"7":{"g":3,"a":2,"dotm":52},"8":{"g":3,"a":10,"dotm":134},"9":{"g":3,"a":6,"dotm":61},"10":{"g":1,"a":4,"dotm":46},"11":{"g":2,"a":0,"dotm":21}}'::jsonb),
  ('DB', '**DB** owns February. _12 G+A, POTM and the Golden Boot_ in the same month, the season''s first double. He''s kept producing since: 57 G+A overall, split almost evenly between 28 goals and 29 assists. **When he''s in the mood, defences don''t get a vote.**', array['Swept both POTM and Golden Boot in February, the only other double winner besides Wale and Ohis', 'February accounts for 37% of his season output', 'Consistent across four months']::text[], '{"1":{"g":0,"a":3},"2":{"g":8,"a":4},"3":{"g":3,"a":4},"4":{"g":4,"a":4},"5":{"g":2,"a":0},"6":{"g":3,"a":2},"7":{"g":0,"a":2},"8":{"g":0,"a":3},"9":{"g":3,"a":1},"10":{"g":4,"a":4},"11":{"g":1,"a":2}}'::jsonb),
  ('Dan J', '**Dan J** does a bit of everything, and most of it better than anyone. Two DOTM titles, _128 points in May_ and 73 in September, plus the September Golden Glove. Add 61 G+A and 46 clean sheets and you have the league''s ultimate utility man. **Second on the all-time DOTM table with 458 points.**', array['Won May Defender of the Month, 128 points from 7G, 6A and 19 CS', '39 G+A, 5th all-time', 'May was his best attacking month: 13 G+A']::text[], '{"1":{"g":6,"a":1},"2":{"g":3,"a":2},"3":{"g":7,"a":1},"4":{"g":4,"a":2,"dotm":46},"5":{"g":7,"a":6,"dotm":128},"6":{"g":2,"a":0,"dotm":31},"7":{"g":2,"a":1,"dotm":42},"8":{"g":4,"a":1,"dotm":64},"9":{"g":7,"a":1,"dotm":73},"10":{"g":0,"a":3,"dotm":46},"11":{"g":1,"a":0,"dotm":28}}'::jsonb),
  ('zeazou', '**Debo** is the purest finisher in the league. _73 goals_, two Golden Boots (May and August), and the only player to score five in a single game week twice. He''s not here to build play. **Give him half a yard and it''s already in the net.**', array['First player to score 5 goals in a single GW twice, GW21 and GW24', '12 goals in May alone, the month''s top scorer', 'Virtually absent in February']::text[], '{"1":{"g":5,"a":0},"2":{"g":0,"a":0},"3":{"g":5,"a":0},"4":{"g":5,"a":5},"5":{"g":12,"a":1},"6":{"g":3,"a":2},"7":{"g":7,"a":1},"8":{"g":15,"a":3},"9":{"g":5,"a":1},"10":{"g":12,"a":3},"11":{"g":4,"a":1}}'::jsonb),
  ('E', '**E** is the threat you don''t see coming. 43 G+A, 24 goals, 19 assists, peaking at _9 G+A in May_. He started the season as a creator and turned himself into a scorer. **Quietly one of the most dangerous players on the pitch.**', array['21 G+A across all five months, above league average', 'May was his best: 5G 4A, both personal bests', 'Early creative role in January evolved into a direct goal threat by May']::text[], '{"1":{"g":1,"a":4},"2":{"g":2,"a":2},"3":{"g":1,"a":1},"4":{"g":1,"a":0},"5":{"g":5,"a":4},"6":{"g":5,"a":3},"7":{"g":5,"a":0},"8":{"g":2,"a":4},"9":{"g":2,"a":1},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Ebuka', '**Ebuka** refuses to pick a lane. _27 goals and 27 assists_, dead level, and an April for the ages: 18 G+A and the Playmaker award. Five assists in GW15 is a joint league record. **Scorer or creator? Both, at the same time.**', array['April was the second-best individual month in league history, 18 G+A (7G + 11A)', 'Set the single-GW assist record in GW15 with 5 assists, joint with Ohis', 'Won the April Playmaker award', '44 G+A, 3rd all-time']::text[], '{"1":{"g":2,"a":2},"2":{"g":3,"a":3},"3":{"g":3,"a":3},"4":{"g":7,"a":11},"5":{"g":6,"a":4},"6":{"g":1,"a":0},"7":{"g":1,"a":2},"8":{"g":2,"a":1},"9":{"g":1,"a":1},"10":{"g":1,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Ekitike', '**Ekitike** arrived late and made it count. July was his month, _POTM and the Golden Boot_, 12 G+A in four weeks. 34 G+A overall. **He comes in bursts. When the burst hits, nobody''s stopping it.**', array['All contributions in May, late arrival', '4 G+A from debut appearances, zero cards']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":3,"a":1},"6":{"g":1,"a":1},"7":{"g":9,"a":3},"8":{"g":2,"a":2},"9":{"g":0,"a":0},"10":{"g":2,"a":5},"11":{"g":4,"a":1}}'::jsonb),
  ('Emmanuel', '**Emmanuel** is a defender who smells goals. March was the statement, _13 G+A in a single month_, and he''s added 40 clean sheets on the defensive tracker. 37 G+A in total. **The card count says he plays on the edge. The numbers say it''s worth it.**', array['March was his defining month, 7G 6A (13 G+A) in six game weeks', 'March output alone would place him 4th in any other month''s POTM race', 'Joint-highest card total in the squad']::text[], '{"1":{"g":2,"a":2},"2":{"g":1,"a":2},"3":{"g":7,"a":6},"4":{"g":2,"a":0,"dotm":45},"5":{"g":4,"a":0,"dotm":71},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":1,"dotm":42},"10":{"g":1,"a":5,"dotm":66},"11":{"g":0,"a":4,"dotm":23}}'::jsonb),
  ('Falo', '**Falo** made his ATL debut in GW36 for Set 1. **The first goal is the hardest. It''s coming.**', array['Debuted in GW36 for Set 1 in August 2026']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Faddy', '**Faddy** is the midfielder every set wants and nobody notices until he''s missing. 28 G+A, _17 of them assists_, plus 43 clean sheets. Not a single card all season. **Reliable doesn''t make headlines. It wins games.**', array['March peak at 5 G+A', 'GW21 his biggest GW: 1G 3A', 'Zero cards all season']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":2},"3":{"g":3,"a":2},"4":{"g":1,"a":0,"dotm":26},"5":{"g":1,"a":3,"dotm":79},"6":{"g":1,"a":3,"dotm":59},"7":{"g":2,"a":4,"dotm":52},"8":{"g":0,"a":2,"dotm":49},"9":{"g":0,"a":1,"dotm":32},"10":{"g":2,"a":0,"dotm":36},"11":{"g":1,"a":0,"dotm":28}}'::jsonb),
  ('Fredrick', '**Fredrick** scored on his ATL debut in GW39. **Debut goals don''t happen by accident.**', array['Scored on debut in GW39 for Set 6 in August 2026']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":1,"a":0,"dotm":8},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('FJ', '**FJ** arrived in GW52 and scored twice on debut for Set 4. **A strong first impression.**', array['Scored twice on his ATL debut in GW52 for Set 4 in November 2026']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":2,"a":0}}'::jsonb),
  ('Fred', '**Fred** built slowly, then exploded. After missing January he hasn''t blanked a month, and August was monstrous, _19 G+A and POTM_, the second-best single month the league has seen. 75 G+A and #4 on the table. **A season that got better every time you looked.**', array['Absent in January but consistent across the following four months', 'May was his best: 6G 3A', 'Never fewer than 5 G+A in any active month']::text[], '{"1":{"g":0,"a":0},"2":{"g":3,"a":2},"3":{"g":3,"a":2},"4":{"g":3,"a":1},"5":{"g":6,"a":3},"6":{"g":3,"a":3},"7":{"g":3,"a":3},"8":{"g":14,"a":5},"9":{"g":5,"a":4},"10":{"g":5,"a":4},"11":{"g":2,"a":1}}'::jsonb),
  ('Gabriel', '**Gabriel** made an immediate impact on debut in GW41: 2G and 2A from Set 1. **One to watch.**', '{}'::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":2,"a":4},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Julius', '**Julius** debuted in GW41 for Set 6. **The journey starts here.**', '{}'::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":1},"10":{"g":4,"a":1},"11":{"g":0,"a":0}}'::jsonb),
  ('Gbaja', '**Gbaja** saved his finest football for the final month. His June was the creative apex of the season for any player: _five goals and seven assists across five game weeks_, earning him the Playmaker of the Month award with the highest assist total of any player in the month''s history. His GW31 session, 2 goals and 3 assists, was the finest individual performance of the final game week, earning him TOTW and MVP honours for Set 4. He is the kind of player who makes those around him better without making himself smaller. **June belonged to Gbaja, and the numbers will remember it long after the session ends.**', array['More assists than goals (13A vs 9G), one of the league''s purest creators', 'March was his standout: 7 G+A including 5A', 'Active across four months']::text[], '{"1":{"g":0,"a":0},"2":{"g":2,"a":2},"3":{"g":2,"a":5},"4":{"g":4,"a":2},"5":{"g":1,"a":4},"6":{"g":5,"a":7},"7":{"g":6,"a":2},"8":{"g":7,"a":4},"9":{"g":0,"a":0},"10":{"g":2,"a":2},"11":{"g":0,"a":6}}'::jsonb),
  ('Iyi', '**Iyi** is a direct, purposeful attacker who peaked in March with a 3-G+A return and has registered _9 G+A, 6 goals and 3 assists_ across his appearances to date. He is primarily a goalscorer rather than a creator, carrying a goal-to-assist ratio that speaks to a player who finishes moves rather than initiating them. **In the right game week, with the right set around him, Iyi can be very difficult to stop.**', array['Active across three months: Feb, Mar, May', 'Goals in February and March, assists in May']::text[], '{"1":{"g":0,"a":0},"2":{"g":2,"a":0},"3":{"g":2,"a":1},"4":{"g":0,"a":1},"5":{"g":1,"a":1},"6":{"g":1,"a":0},"7":{"g":0,"a":1},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Jerrie', '**Jerrie** is unlike any goalkeeper this league has produced. _30 clean sheets, 23 assists, and 17 goals_, figures that would flatter a midfielder and astonish a keeper. She saved two penalties in a single game week in GW14, won the June Golden Glove with 8 clean sheets, and remained the division''s most complete goalkeeper across every month she played. She and Bass represent a generational pair of keepers rarely seen in any league, but Jerrie is the one the opposition fears most when it counts. **She is not just the second-best keeper in ATL history. She may be the most complete player in it.**', array['28 clean sheets, second all-time behind Bass', 'Saved 2 penalties in GW14, a league first', 'Holds the single-GW CS record (4) alongside Bass and Busayo', 'Won the May Golden Glove, ending Bass''s three-month run', '10 assists in May alone, most by any keeper in a single month']::text[], '{"1":{"g":4,"a":1},"2":{"g":2,"a":3},"3":{"g":4,"a":6},"4":{"g":6,"a":2,"dotm":46},"5":{"g":0,"a":10,"dotm":120},"6":{"g":1,"a":1,"dotm":50},"7":{"g":1,"a":2,"dotm":12},"8":{"g":1,"a":1,"dotm":62},"9":{"g":1,"a":1,"dotm":20},"10":{"g":1,"a":0,"dotm":28},"11":{"g":0,"a":1,"dotm":12}}'::jsonb),
  ('Killz', '**Killz** is a combative defender with a notable scoring record for his position. He finished with _14 G+A, 6 goals and 8 assists_, and his June was his finest defensive month: 12 DOTM points as part of Set 5''s campaign, despite collecting a red card in the final game week of the season. He is not a passive defender; he carries the ball forward with purpose and arrives into the penalty area at a rate that most outfield players would respect. **Killz does not defend from a distance, he defends from the front.**', array['4 yellow cards, joint-highest with Triumph', 'Contributed in all five months', 'Runner-up in the April DOTM (53pts)']::text[], '{"1":{"g":1,"a":0},"2":{"g":1,"a":1},"3":{"g":1,"a":2},"4":{"g":0,"a":1,"dotm":53},"5":{"g":2,"a":2,"dotm":100},"6":{"g":1,"a":2,"dotm":64},"7":{"g":1,"a":1,"dotm":52},"8":{"g":0,"a":0,"dotm":80},"9":{"g":0,"a":1,"dotm":22},"10":{"g":1,"a":0,"dotm":30},"11":{"g":0,"a":1,"dotm":19}}'::jsonb),
  ('Skinny N', '**Kunle** is, without qualification, the finest individual player in ATL history. He closed the 2025/26 season with _79 goal contributions, 56 goals and 23 assists_, breaking every meaningful attacking record the league had ever produced. He won the Player of the Month award three times, set the single-month record with 21 G+A in April, and was the only player in the division to register double-digit contributions in four separate months. He does not have a quiet patch. He does not have a bad game week. **Kunle simply performs, and the numbers follow.**', array['Holds the POTM record, 21 G+A in April 2026', 'Won POTM twice: January (shared) and April (outright)', 'Set the single-GW goals record in GW15 with 5 goals', '47 goals this season, most in the league. 67 G+A total after GW27', 'Zero cards in 27 game weeks']::text[], '{"1":{"g":9,"a":4},"2":{"g":3,"a":6},"3":{"g":7,"a":2},"4":{"g":15,"a":6},"5":{"g":10,"a":1},"6":{"g":12,"a":4},"7":{"g":2,"a":1},"8":{"g":7,"a":1},"9":{"g":10,"a":1},"10":{"g":10,"a":2},"11":{"g":3,"a":1}}'::jsonb),
  ('Mustee', '**Mustee** made his ATL debut in GW38 for Set 1. **The story begins here.**', array['Debuted in GW38 for Set 1 in August 2026']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":2,"dotm":29},"9":{"g":0,"a":3,"dotm":38},"10":{"g":0,"a":0,"dotm":35},"11":{"g":1,"a":0,"dotm":11}}'::jsonb),
  ('Black and fly', '**Moses** is one of the most underappreciated defensive playmakers in the league. He finished with _29 G+A, 10 goals and 19 assists_ despite playing almost exclusively in a deeper, more conservative defensive role. His February was his defining month: 9 G+A and the most assists of any defender that month. The combination of a disciplined positional structure and a creative instinct in transition makes him one of the most valuable players to have on a set without a recognised number ten. **Moses does not ask for credit. He earns it quietly, then lets the table speak.**', array['More assists than goals (18A vs 10G), one of the league''s purest creators', 'May was his peak creative month: 8 assists', 'Consistent across all five months']::text[], '{"1":{"g":2,"a":3},"2":{"g":5,"a":4},"3":{"g":1,"a":2},"4":{"g":1,"a":1,"dotm":25},"5":{"g":1,"a":8,"dotm":84},"6":{"g":0,"a":1,"dotm":5},"7":{"g":0,"a":0,"dotm":5},"8":{"g":1,"a":5,"dotm":39},"9":{"g":0,"a":0},"10":{"g":1,"a":0,"dotm":28},"11":{"g":0,"a":2,"dotm":9}}'::jsonb),
  ('Nteoniro', '**Nteoniro**, known to the league as Niro, is a direct attacker who contributed _1 goal and 1 assist_ in his limited January appearances. He carries the ball with purpose and plays without inhibition, and a yellow card collected during the season indicates a player who competes aggressively. **With more sessions and more game weeks, Niro has the profile of a player who accumulates fast.**', array['Scored and assisted in January']::text[], '{"1":{"g":1,"a":1},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Ohis', '**Ohis** is among the most naturally gifted forwards ATL has seen. His March was extraordinary, _20 G+A, a shared Golden Boot, and the Player of the Month award_, a haul that made him and his brother AK the first siblings in league history to each win POTM in the same season. He arrived in June with a hat-trick and an assist in GW30, then added another goal in GW31, finishing his season with 37 G+A and a reputation that extended far beyond his game week appearances. **Ohis plays as though the goal was never in doubt, because, for him, it rarely is.**', array['March 2026 was one of the best individual months in league history, 20 G+A (9G + 11A)', 'Set the single-GW assist record in GW10 with 5 assists, joint with Ebuka', 'Won March POTM, first siblings to both win with brother AK', 'Hat-trick and 1 assist in GW30, debut POTM contribution', 'Part of Set 1 TOTW in GW30']::text[], '{"1":{"g":3,"a":0},"2":{"g":1,"a":0},"3":{"g":9,"a":11},"4":{"g":5,"a":2},"5":{"g":0,"a":1},"6":{"g":4,"a":1},"7":{"g":0,"a":1},"8":{"g":1,"a":0},"9":{"g":1,"a":1},"10":{"g":6,"a":1},"11":{"g":1,"a":0}}'::jsonb),
  ('oreos', '**Oriola** was the model of month-on-month reliability in the 2025/26 season. _31 G+A, no blank months, no disciplinary record_, a profile that speaks to a player of exceptional consistency and professional discipline. His June was his most complete campaign: 9 G+A as POTM runner-up and 77 DOTM points as third in the Defender of the Month standings, including four assists in a single GW29 session. **In a league of moments, Oriola built a season out of habits, and the table reflects it.**', array['Contributed in all five months', '22 G+A, above league average', 'Zero cards in 27 game weeks']::text[], '{"1":{"g":2,"a":4},"2":{"g":1,"a":1},"3":{"g":3,"a":2},"4":{"g":2,"a":1,"dotm":48},"5":{"g":3,"a":3,"dotm":73},"6":{"g":4,"a":5,"dotm":77},"7":{"g":0,"a":0,"dotm":30},"8":{"g":1,"a":2,"dotm":77},"9":{"g":1,"a":3,"dotm":33},"10":{"g":2,"a":5,"dotm":73},"11":{"g":0,"a":1,"dotm":22}}'::jsonb),
  ('Mayor', '**Mayor** made his ATL debut at the Salami Cup on 1st October 2026, lining up for _The Syndicate FC_ alongside Chukkie, Tony and Alayo. **His first contribution is still to come.**', array['Salami Cup debut for The Syndicate FC, 1st October 2026 (GW46)']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Delani', '**Delani** made his ATL debut at the Salami Cup on 1st October 2026 with _Hawks FC_, who finished runners-up on 10 points, level with Predators FC on points and goal difference. **A strong first outing to build on.**', array['Salami Cup debut for Hawks FC, 1st October 2026 (GW46)', 'Part of the Hawks side that finished runners-up, level on points and GD with the champions']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Yusuf', '**Yusuf** Set 5 player who debuted in GW47, October 2026.', '{}'::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Tomi', '**Tomi** was one of the most quietly devastating players of the season. _37 goals and 11 assists, 48 G+A in total_, produced with a consistency that attracted little fanfare but registered on every table. His best month came in May, where he contributed 12 G+A and shared the Golden Boot with Ohis. He was never the headline act, never the award winner, but his output sat comfortably in the top three for most of the calendar year. **Tomi is the player the scoreboard thanks but the crowd forgets, until the table tells the truth.**', array['Won the Q1 Golden Boot with 21 goals across January to March', 'Scored exactly 2 goals in four consecutive GWs (GW9-12), record for sustained consistency', '4 goals in a single GW four separate times', '47 G+A, 4th all-time', 'Zero cards in 27 game weeks']::text[], '{"1":{"g":6,"a":2},"2":{"g":6,"a":1},"3":{"g":9,"a":2},"4":{"g":7,"a":2},"5":{"g":8,"a":4},"6":{"g":1,"a":0},"7":{"g":1,"a":0},"8":{"g":8,"a":0},"9":{"g":8,"a":3},"10":{"g":3,"a":1},"11":{"g":3,"a":0}}'::jsonb),
  ('Tien', '**Tien** made an immediate impact on debut, clean sheet and an assist. **The story begins here.**', array['Recorded a clean sheet and an assist on GW40 debut']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":2,"dotm":22},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Tony Vodka', '**Tony** is a box-threat defender with an eye for goal that his defensive classification understates. He has contributed _17+ G+A, 10 goals and 7 assists_ across the campaign, and was a consistent DOTM points earner through his ability to occupy clean sheet positions while registering at the other end. His July was a standout month, he led the DOTM standings at one point with 38 points across GW32 and GW33. **At ten goals from a defensive position, Tony does not need a forward''s role to play like one.**', array['GW22 his standout: 2G 1A, earning GW MVP', 'Contributed across all five months', '7 goals and 7 assists, most perfectly balanced G/A ratio in the squad']::text[], '{"1":{"g":1,"a":1},"2":{"g":1,"a":0},"3":{"g":1,"a":3},"4":{"g":1,"a":1,"dotm":24},"5":{"g":3,"a":2,"dotm":78},"6":{"g":3,"a":0,"dotm":54},"7":{"g":1,"a":1,"dotm":60},"8":{"g":0,"a":0,"dotm":45},"9":{"g":1,"a":0,"dotm":45},"10":{"g":0,"a":0,"dotm":45},"11":{"g":1,"a":0,"dotm":18}}'::jsonb),
  ('Triumph', '**Triumph** made history in two separate months and became the greatest defender this league has ever formally recognised. He won the inaugural Defender of the Month award in April with 78 points, then reclaimed it in June with _85 points, 2 goals, 5 assists, 13 clean sheets_, edging Oliver by a single point in the closest DOTM race the competition has ever produced. He currently leads the all-time DOTM standings and became the _first player in ATL history to reach 300 career DOTM points_, a record he continues to extend. **Triumph has not just defended well this season. He has defined what defending well looks like in ATL.**', array['Won the inaugural Defender of the Month award in April, the first ever DOTM winner in ATL history', '18 G+A across the season, above league average', '5 yellows and 1 red, added a card in GW27']::text[], '{"1":{"g":1,"a":2},"2":{"g":0,"a":2},"3":{"g":0,"a":1},"4":{"g":2,"a":4,"dotm":78},"5":{"g":2,"a":4,"dotm":72},"6":{"g":2,"a":5,"dotm":85},"7":{"g":2,"a":1,"dotm":48},"8":{"g":2,"a":5,"dotm":88},"9":{"g":1,"a":1,"dotm":35},"10":{"g":1,"a":5,"dotm":58},"11":{"g":0,"a":0,"dotm":10}}'::jsonb),
  ('Uzkhov', '**Uzo** has been one of the more consistent contributors at the top of the standings for much of the season. He finished with _27 G+A, 19 goals and 8 assists_, with his best individual month coming in April where he produced 9 G+A. He carries the ball with conviction in tight spaces and his goals tend to arrive in moments of genuine pressure rather than as gift goals. **He does not always make the headline, but his name is rarely absent from the scorer''s sheet.**', array['Missed January but contributed every month after', '27 G+A across four active months, well above average', 'Back-to-back 5-goal months in April and May']::text[], '{"1":{"g":0,"a":0},"2":{"g":4,"a":1},"3":{"g":5,"a":1},"4":{"g":5,"a":4},"5":{"g":5,"a":2},"6":{"g":0,"a":0},"7":{"g":3,"a":4},"8":{"g":4,"a":1},"9":{"g":10,"a":2},"10":{"g":3,"a":2},"11":{"g":0,"a":1}}'::jsonb),
  ('Vinny', '**Vinny** is a composed, technically proficient defender who reads the game better than his modest numbers suggest. He finished with _9 G+A, 7 goals and 2 assists_, and his June campaign as part of Set 4''s TOTW was his most complete period, contributing 25 DOTM points with 4 clean sheets and a goal-and-assist double. **Vinny is at his best when everything around him is functioning, and then he makes it function better.**', array['Most output in May, 4 goals after near-total absence', 'Scored 2 in both GW24 and GW25, best consecutive run']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":1,"a":1},"4":{"g":1,"a":0,"dotm":28},"5":{"g":4,"a":0,"dotm":62},"6":{"g":1,"a":1,"dotm":55},"7":{"g":0,"a":0,"dotm":35},"8":{"g":0,"a":1,"dotm":37},"9":{"g":0,"a":0,"dotm":20},"10":{"g":1,"a":0,"dotm":18},"11":{"g":0,"a":1,"dotm":7}}'::jsonb),
  ('Mase', '**Obi** scored on debut in GW42 (September 2026). **The story begins.**', '{}'::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":1,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Willis', '**Willis** debuted in GW42 with 2 assists. **A creator from day one.**', '{}'::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":2},"10":{"g":0,"a":0,"dotm":25},"11":{"g":0,"a":0,"dotm":4}}'::jsonb),
  ('Wale', '**Wale** does not score goals, he engineers them. His _34 assists across the 2025/26 season represent the highest single-season assist total in ATL history_, a record he extended deep into June with five further contributions. His May was the most dominant creative month any player produced all season: 11 assists alone, double winner, active in all seven game weeks. He finished the campaign as June Playmaker runner-up despite not playing regularly in every set. **In an era of scorers, Wale reminded the league that the man who sets up the goal deserves the ovation too.**', array['Won both POTM and Playmaker in May, second double winner after DB in February', 'The league''s all-time assist leader with 30 assists after GW27', 'GW25 produced 3G 4A = 7 G+A, his best ever individual GW', 'Contributed in every one of the 7 May game weeks']::text[], '{"1":{"g":7,"a":5},"2":{"g":4,"a":3},"3":{"g":7,"a":5},"4":{"g":0,"a":5},"5":{"g":4,"a":11},"6":{"g":1,"a":5},"7":{"g":1,"a":3},"8":{"g":6,"a":7},"9":{"g":4,"a":6},"10":{"g":2,"a":2},"11":{"g":2,"a":3}}'::jsonb),
  ('Yaya', '**Yaya** was the league''s most creative defender for much of the early season. He finished with _24 G+A, 6 goals and 18 assists_, and his January was historically exceptional: 12 G+A and the January Playmaker of the Month award, the most assists recorded by any player in the opening month of the campaign. He reads the game from deep and rarely wastes a possession when a line-breaking pass is available. **Yaya''s January set a standard the rest of the league spent the entire year trying to match.**', array['January was his defining month, 10 assists in four game weeks, winning Playmaker', '10 assists in January is the highest single-month assist total in league history', 'Quiet thereafter: 8 G+A across the remaining four months']::text[], '{"1":{"g":2,"a":10},"2":{"g":1,"a":3},"3":{"g":0,"a":0},"4":{"g":2,"a":2,"dotm":15},"5":{"g":1,"a":3,"dotm":17},"6":{"g":0,"a":0},"7":{"g":2,"a":1,"dotm":33},"8":{"g":2,"a":1,"dotm":20},"9":{"g":0,"a":0},"10":{"g":5,"a":2,"dotm":18},"11":{"g":0,"a":0}}'::jsonb),
  ('Folarin', '**Folarin** is one of the most reliable defensive clean sheet accumulators in the league, finishing with _12 clean sheets_ as part of consistently organised defensive sets. His May was his most productive month at 4 G+A, and his DOTM points profile across June, 35 points, placed him inside the top fifteen for the month. He rarely contributes at the attacking end but his defensive discipline gives sets a structural foundation that more attack-minded players tend to benefit from. **Folarin keeps the back door closed so others can focus on opening the front one.**', array['12 clean sheets in the DOTM period, 6th best among all 29 defenders']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":1,"dotm":17},"5":{"g":2,"a":2,"dotm":55},"6":{"g":0,"a":0,"dotm":35},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":1,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('George', '**George** is a measured, technically sound defender who accumulates clean sheets without drawing unnecessary attention. His _7 clean sheets_ and 5 G+A across the season include a best month in April, where his combination of defensive solidity and brief attacking contributions produced his most complete personal return. **He is the kind of player who makes a set better simply by being in it.**', array['7 clean sheets and 3 assists in April']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":3,"dotm":41},"5":{"g":0,"a":0},"6":{"g":1,"a":1},"7":{"g":0,"a":2},"8":{"g":0,"a":0},"9":{"g":0,"a":1},"10":{"g":0,"a":1,"dotm":7},"11":{"g":0,"a":0}}'::jsonb),
  ('Laru', '**Laru** is a composed defensive player whose season was defined more by organisational contribution than personal output. He produced _4 clean sheets and 2 assists_, no goals, across his appearances, with his April the most active period. **His value is the kind that shows up in a set''s defensive record rather than its G+A table.**', array['4 clean sheets and 2 assists during April']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":2,"dotm":24},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0,"dotm":15},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Dami', '**Dami** appeared in the September DOTM tracker. **A new defender on record.**', '{}'::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":2,"dotm":19},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Dante', '**Dante** is a scoring defender whose June campaign was the strongest single-month defensive performance of his career. He produced _75 DOTM points across five game weeks_, 2 goals, 3 assists, 12 clean sheets, finishing fourth in the final standings and earning the Set 5 TOTW with a brace in GW31. His season total of 5 G+A and 5 clean sheets masks a player who, at full involvement, is one of the most dangerous defenders in the division. **Dante''s June was a trailer for everything he is capable of when the environment is right.**', array['5 clean sheets across the DOTM period', 'Red card in April significantly reduced his points tally']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0,"dotm":3},"5":{"g":0,"a":0,"dotm":20},"6":{"g":3,"a":2,"dotm":75},"7":{"g":0,"a":2,"dotm":34},"8":{"g":0,"a":2,"dotm":24},"9":{"g":1,"a":3,"dotm":22},"10":{"g":2,"a":2,"dotm":69},"11":{"g":0,"a":2,"dotm":23}}'::jsonb),
  ('Leonard', '**Leonard** is a composed, technically assured defender who contributed _5 G+A, 3 goals and 2 assists_ alongside 3 clean sheets. His May was his most active month, and he operated primarily in defensive structures that limited his attacking licence but showed his positional intelligence. **Leonard does the quiet work that only becomes visible when it stops happening.**', array['Scored in both GW24 and GW25', '2G 1A 3CS across May game weeks']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":3,"a":2,"dotm":23},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":2,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Ukeme', '**Ukeme** is a direct and physical forward who contributed _3 goals_ across May appearances, operating with a straightforward style that prioritises goal threat over creative involvement. **He may not have the assists, but every set that includes him in the final third is harder to defend against.**', array['All 3 goals scored in GW20, opening game week of May']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":3,"a":0,"dotm":19},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Famade', '**Famade** contributed 1 goal and 3 clean sheets across a limited run of appearances. He is a defender with a physical presence and a natural positional understanding that makes him difficult to bypass in one-on-one situations. **A more extended run of game weeks would give this league a clearer picture of what he offers.**', array['1 goal and 3 clean sheets across April and May', 'Zero cards, clean disciplinary record']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":1,"a":0,"dotm":13},"5":{"g":0,"a":0,"dotm":5},"6":{"g":0,"a":0,"dotm":13},"7":{"g":2,"a":2,"dotm":50},"8":{"g":1,"a":1,"dotm":30},"9":{"g":0,"a":0},"10":{"g":1,"a":0,"dotm":13},"11":{"g":0,"a":0}}'::jsonb),
  ('Oliver', '**Oliver** spent most of the season in steady, unremarkable service, and then June arrived. He produced _84 DOTM points in a single month_, finishing just one point behind Triumph in the closest Defender of the Month race in league history, with 14 clean sheets and 5 assists across five game weeks. His season total of 8 G+A tells a different story than his June tells, but it is the June story that will be remembered. **One point. One month. One of the finest defensive campaigns any ATL player has ever produced.**', array['Scored in GW21', '3 clean sheets during April']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":1,"a":0,"dotm":18},"5":{"g":0,"a":0},"6":{"g":2,"a":5,"dotm":84},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":3,"a":1,"dotm":56},"10":{"g":2,"a":3,"dotm":74},"11":{"g":1,"a":2,"dotm":32}}'::jsonb),
  ('Tobi', '**Tobi** marked his ATL debut in GW33 with a goal for Set 1, the most direct way to introduce yourself to the league. **The rest of the story has not yet been written.**', array['Scored on ATL debut in GW33 for Set 1']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":1,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":3,"a":1},"11":{"g":0,"a":0}}'::jsonb),
  ('Topla', '**Topla** joined the league in the final weeks of the season and is yet to register a goal or assist in official competition. What he brings to the group is an attitude and a work rate that the ATL environment typically rewards over time. **The season that counts for Topla has not started yet.**', array['Made ATL debut in GW28 as part of Set 4']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Seyi', '**Seyi** is a direct, clinical attacker who debuted in June and immediately made his presence felt. He scored in his first three consecutive game week appearances, _5 goals across GW28 and GW29_, without registering an assist, a profile that marks him as a natural finisher rather than a possession player. **Five goals on debut in the league is a statement. The question now is whether Seyi returns to build on it.**', array['Hat-trick on debut in GW28, 3 goals in first ATL appearance', 'Most prolific debut of the 2025/26 season']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":5,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Ette', '**Ette** made his ATL debut in GW28 and produced an immediate impact, _2 goals and 1 assist in a single game week_, one of the more impressive debut contributions the league has recorded in recent months. He is a purposeful attacker who scores on instinct, and the fact that he arrived in the final month of the season only raises anticipation for what follows. **Ette debuted with a statement. The league will be watching for the follow-up.**', array['2G 1A on debut in GW28, instant impact for Set 1', 'Part of the TOTW side that finished the session top of the standings']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":2,"a":1},"7":{"g":1,"a":2},"8":{"g":0,"a":0},"9":{"g":1,"a":1},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Dønatellø', '**Raphael** marked his ATL debut in GW29 with a goal, announcing his arrival with the kind of finish that reflects a player at ease in front of goal from the first opportunity given to him. He is a natural finisher with a direct approach and an instinct for the penalty area. **One debut goal tells a story. The rest of the chapters have not yet been written.**', array['Debut goal in GW29 for Set 6', 'First ATL appearance']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":1,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Gbolahan', '**Gbolahan** arrived quietly and has made his mark through craft rather than volume. He has contributed across multiple months, with his June assists and July goal highlighting a player whose influence grows with game time. **Gbolahan is a player who improves the sets he plays in, and the league will continue to see more of him.**', array['Scored on his first tracked GW in GW29 for Set 3 TOTW']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":2,"a":2},"7":{"g":2,"a":1},"8":{"g":0,"a":0},"9":{"g":1,"a":0},"10":{"g":3,"a":1},"11":{"g":0,"a":0}}'::jsonb),
  ('Dozie', '**Dozie** made his ATL debut in GW30 as part of Set 3 and is yet to register a goal or assist in official competition. He arrived with purpose and integrated himself into the group without difficulty. **The next time Dozie takes to the pitch, the league will know more about what he intends to do with it.**', array['Made ATL debut in GW30 as part of Set 3']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":2,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Anayo', '**Anayo** is a creator who rarely scores himself but consistently finds team-mates in better positions. His _3 assists_ across the season, including contributions in April, reflect a player whose influence registers in the work of others rather than on the personal scoresheet. **Not every valuable player scores. Anayo is the proof.**', array['3 assists in April, a pure creative contributor']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":3,"dotm":6},"5":{"g":0,"a":0},"6":{"g":0,"a":0,"dotm":6},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Chisom', '**Chisom** is a quiet, reliable defensive presence who registered _5 clean sheets and 1 assist_ across April appearances. He prioritises defensive structure over personal output and rarely makes the kind of error that costs a clean sheet. **Chisom is the kind of player a set trusts without needing to discuss.**', array['5 clean sheets across April and May', 'Active across both months of the DOTM window']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":1,"dotm":12},"5":{"g":0,"a":0,"dotm":15},"6":{"g":0,"a":0,"dotm":5},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0,"dotm":5},"10":{"g":0,"a":0},"11":{"g":1,"a":0}}'::jsonb),
  ('Machado', '**Alayo** is a measured, defensive-minded player with a calm positional game that earns clean sheets at a decent rate, _7 across the season_, and a modest but present attacking contribution of 4 G+A. His May was his most productive period overall. **He is a reliable organisational presence who makes simple things look effortless.**', array['7 clean sheets in the DOTM period, 5th highest among all defenders', 'GW25 goal and assist his best attacking game week']::text[], '{"1":{"g":0,"a":0},"2":{"g":1,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0,"dotm":29},"5":{"g":1,"a":2,"dotm":5},"6":{"g":0,"a":0,"dotm":36},"7":{"g":1,"a":2,"dotm":61},"8":{"g":3,"a":0,"dotm":76},"9":{"g":0,"a":0},"10":{"g":1,"a":1,"dotm":15},"11":{"g":0,"a":0,"dotm":20}}'::jsonb),
  ('Bike', '**Doyin** is a creative defender whose best form arrived in February and May, contributing _4 G+A alongside 2 assists and 4 clean sheets_ across those months. He tends to operate most effectively in sets where he is given licence to step into wider creative positions rather than anchoring deep. **Given the right structure around him, Doyin is more dangerous than a four-G+A season suggests.**', array['GW26 debut, 1G 1A in first appearance', 'Named GW26 Player of the Week', 'Only player to win Player of the Week on his debut']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":1,"a":1,"dotm":25},"6":{"g":0,"a":2},"7":{"g":0,"a":0},"8":{"g":0,"a":0,"dotm":10},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Joe', '**Joe** is a versatile forward whose June campaign produced his most complete returns of the season, contributing across GW29 and GW31 with goals and assists in a total of _5 G+A_. He does not dominate any individual session, but he contributes to most of those he plays in, which in itself is a form of consistency worth recognising. **Joe''s best football may still be ahead of him, and that is not a criticism.**', array['Goal and assist in GW20, opening game week of May']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":1,"a":1},"6":{"g":2,"a":1},"7":{"g":3,"a":1},"8":{"g":1,"a":3},"9":{"g":1,"a":1},"10":{"g":4,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Oreva', '**Oreva** is an energetic forward who found her most productive form in the closing weeks of the season. Her June campaign produced _5 G+A, 3 goals and 1 assist across three GWs_, including a brace in GW31 as part of Set 1. She operates with intensity and directness, and the yellow card she collected in GW30 was the only blemish on a clean disciplinary record. **Oreva leaves the season with momentum, and that is exactly when momentum matters most.**', array['Scored on debut in GW26, the final game week of the season']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":1,"a":0},"6":{"g":3,"a":1},"7":{"g":2,"a":0},"8":{"g":0,"a":0},"9":{"g":3,"a":3},"10":{"g":1,"a":2},"11":{"g":0,"a":1}}'::jsonb),
  ('Olamide', '**Olamide** produced a January that announced his presence, _5 G+A_ in his best individual month, before the season settled into a moderate contribution pattern. He finished with 10 G+A across the campaign, with a balance of goals and assists that reflects a player comfortable operating in multiple phases of a possession. **His ceiling is visible. Whether he reaches it is the question the next season will answer.**', array['Featured for Team 5 in GW25']::text[], '{"1":{"g":2,"a":3},"2":{"g":1,"a":1},"3":{"g":2,"a":1},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":1,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Mateta', '**Mateta** has produced the kind of single-goal ATL contribution that hints at a forward with natural ability but limited opportunity. His May appearance produced a goal, suggesting a player who can be clinical when given a role in the attacking third. **What Mateta does with more game time is a conversation the next season will open.**', array['Scored in GW20']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":1,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Harper', '**Harper** contributed _2 assists_ in May appearances, operating with a creative instinct that found team-mates in dangerous positions without needing to be the one who finishes. His involvement was limited but purposeful. **Given a fuller campaign, Harper''s creative profile could develop into something more substantial.**', array['Assisted in both GW20 and GW21']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":2},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('CJ', '**CJ** is registered in the ATL system but is yet to produce a recorded goal or assist contribution. His involvement to date has been part of a process of integration into the league''s culture and competition structure. **The first contribution, when it arrives, will tell the league everything it needs to know.**', array['Debuted in GW26, the season final game week']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Damola', '**Damola** is registered in the league and is in the process of building a statistical profile within the ATL system. He has not yet recorded a goal or assist contribution in official competition. **Every player''s story starts somewhere. Damola''s is still in its opening chapter.**', array['Debuted in GW26, the season final game week']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":0,"a":0},"6":{"g":0,"a":0},"7":{"g":0,"a":0},"8":{"g":0,"a":0},"9":{"g":0,"a":0},"10":{"g":0,"a":0},"11":{"g":0,"a":0}}'::jsonb),
  ('Iyiola', '**Iyiola** is a composed defender with both a goalscoring instinct and a clean disciplinary record. He contributed _3 G+A, 3 goals and 4 clean sheets_, and produced his best individual performance in May before an absence curtailed his June involvement. **He is a player who can change a game when given the right opportunity, and his record in the DOTM system reflects that.**', array['3 goals in May (GW20, GW21, GW23)', '4 clean sheets in GW27, first DOTM submission', 'Returned to the squad in June as part of Team 1']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0},"5":{"g":3,"a":0},"6":{"g":0,"a":0,"dotm":38},"7":{"g":1,"a":0,"dotm":50},"8":{"g":2,"a":0,"dotm":41},"9":{"g":2,"a":0,"dotm":36},"10":{"g":0,"a":1,"dotm":10},"11":{"g":2,"a":0,"dotm":11}}'::jsonb),
  ('Ikah', '**Ikah** is a clean-sheet specialist who earns his DOTM points through positional discipline rather than attacking presence. His _7 clean sheets_ across the season are the product of consistent defensive structure, and his 22-point GW31 DOTM haul, 4 clean sheets and an assist as part of Set 4''s TOTW, was the finest individual defensive game week of his season. **Ikah''s contributions are most visible in the moments when the opposition does not score.**', array['7 clean sheets across the DOTM period, level with Alayo for 5th best', 'Registered an assist in GW20']::text[], '{"1":{"g":0,"a":0},"2":{"g":0,"a":0},"3":{"g":0,"a":0},"4":{"g":0,"a":0,"dotm":15},"5":{"g":0,"a":1,"dotm":22},"6":{"g":0,"a":1,"dotm":10},"7":{"g":0,"a":3,"dotm":16},"8":{"g":2,"a":3,"dotm":22},"9":{"g":0,"a":0},"10":{"g":4,"a":0,"dotm":13},"11":{"g":1,"a":1}}'::jsonb)
) as a(nickname, write_up, facts, months)
join players p on lower(p.nickname) = lower(a.nickname)
on conflict (player_id) do update
  set write_up = excluded.write_up, facts = excluded.facts, months = excluded.months, updated_at = now();
